//! Emoji picker logic (V4). Dataset: `data/emoji.tsv`, generated by `scripts/gen-emoji.py` from a local
//! Unicode `emoji-test.txt`, embedded at compile time. Columns: emoji, name, keywords, group, skin-tone
//! variants (space separated; folded under the base emoji).
//!
//! `search(query, &Frecency, now)`: empty query lists recents first (by frecency), then the rest in
//! dataset order; otherwise ranked by `ranker` with a capped frecency boost. `record_use` feeds frecency.
use std::sync::OnceLock;

use super::frecency::Frecency;
use super::ranker::{self, Item};

const DATA: &str = include_str!("../../data/emoji.tsv");
const BOOST_CAP: f64 = 1500.0;

#[derive(Clone, Debug)]
pub struct Emoji {
    pub ch: String,
    pub name: String,
    pub keywords: String,
    pub group: String,
    /// Skin tone variants (empty when the emoji has none).
    pub variants: Vec<String>,
}

pub fn all() -> &'static [Emoji] {
    static CELL: OnceLock<Vec<Emoji>> = OnceLock::new();
    CELL.get_or_init(|| DATA.lines().filter_map(parse_line).collect())
}

fn parse_line(l: &str) -> Option<Emoji> {
    let mut f = l.split('\t');
    let ch = f.next().filter(|s| !s.is_empty())?.to_string();
    Some(Emoji {
        ch,
        name: f.next()?.to_string(),
        keywords: f.next().unwrap_or("").to_string(),
        group: f.next().unwrap_or("").to_string(),
        variants: f.next().unwrap_or("").split_whitespace().map(String::from).collect(),
    })
}

fn fid(ch: &str) -> String {
    format!("emoji:{ch}")
}

/// Record a pick (`ch` may be a base emoji or a skin tone variant: variants count for the base).
pub fn record_use(fr: &mut Frecency, ch: &str, query: &str, now: i64) {
    let base = all().iter().find(|e| e.ch == ch || e.variants.iter().any(|v| v == ch));
    fr.record_launch(&fid(base.map_or(ch, |e| e.ch.as_str())), query, now);
}

pub fn search(query: &str, fr: &Frecency, now: i64) -> Vec<&'static Emoji> {
    let list = all();
    if query.trim().is_empty() {
        let mut recents: Vec<(&Emoji, f64)> =
            list.iter().map(|e| (e, fr.score(&fid(&e.ch), now))).filter(|(_, s)| *s > 0.5).collect();
        recents.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        let mut out: Vec<&Emoji> = recents.into_iter().map(|r| r.0).collect();
        let n = out.len();
        let rest: Vec<&Emoji> = list.iter().filter(|e| !out[..n].iter().any(|o| o.ch == e.ch)).collect();
        out.extend(rest);
        return out;
    }
    let items: Vec<Item> = list
        .iter()
        .enumerate()
        .map(|(i, e)| Item {
            id: i.to_string(),
            title: e.name.clone(),
            keywords: e.keywords.split_whitespace().map(String::from).collect(),
            alias: None,
        })
        .collect();
    let mut scored: Vec<(usize, i64)> = ranker::rank(query, &items)
        .into_iter()
        .map(|(it, s)| {
            let i: usize = it.id.parse().unwrap_or(0);
            (i, s + (fr.score(&fid(&list[i].ch), now) * 10.0).min(BOOST_CAP) as i64)
        })
        .collect();
    scored.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    scored.into_iter().map(|(i, _)| &list[i]).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dataset_is_big_and_clean() {
        assert!(all().len() >= 1500, "{}", all().len());
        assert!(all().iter().all(|e| !e.name.is_empty() && !e.ch.is_empty()));
    }

    #[test]
    fn no_skin_tone_rows_but_variants_folded() {
        assert!(all().iter().all(|e| !e.name.contains("skin tone")));
        let w = all().iter().find(|e| e.name == "waving hand").unwrap();
        assert_eq!(w.variants.len(), 5);
    }

    #[test]
    fn heart_finds_hearts() {
        let r = search("heart", &Frecency::default(), 0);
        assert!(r.len() > 10);
        assert!(r.iter().take(10).all(|e| e.name.contains("heart")));
        assert!(r.iter().any(|e| e.name == "red heart"));
    }

    #[test]
    fn exact_name_first() {
        assert_eq!(search("red heart", &Frecency::default(), 0)[0].name, "red heart");
    }

    #[test]
    fn keyword_and_no_match() {
        let r = search("rocket", &Frecency::default(), 0);
        assert_eq!(r[0].ch, "🚀");
        assert!(search("zzzzqqq", &Frecency::default(), 0).is_empty());
    }

    #[test]
    fn empty_query_lists_everything_recents_first() {
        let mut fr = Frecency::default();
        assert_eq!(search("", &fr, 0).len(), all().len());
        record_use(&mut fr, "🚀", "", 100);
        record_use(&mut fr, "🎉", "", 200);
        let r = search("", &fr, 300);
        assert_eq!(r[0].ch, "🎉");
        assert_eq!(r[1].ch, "🚀");
        assert_eq!(r.len(), all().len());
    }

    #[test]
    fn variant_use_counts_for_base() {
        let mut fr = Frecency::default();
        record_use(&mut fr, "👋🏽", "", 10);
        assert_eq!(search("", &fr, 10)[0].ch, "👋");
    }

    #[test]
    fn recent_boosts_within_query() {
        let mut fr = Frecency::default();
        let base = search("heart", &fr, 0);
        let pick = base[7].ch.clone();
        record_use(&mut fr, &pick, "heart", 1000);
        record_use(&mut fr, &pick, "heart", 1001);
        let r = search("heart", &fr, 1002);
        let pos = r.iter().position(|e| e.ch == pick).unwrap();
        assert!(pos < 7, "{pos}");
    }
}
